from langfuse import Langfuse
from langfuse.decorators import observe, langfuse_context
import openai

langfuse = Langfuse()  # reads LANGFUSE_PUBLIC_KEY, LANGFUSE_SECRET_KEY from env
client = openai.OpenAI()

@observe()  # wraps the whole pipeline as a single root trace
def answer_question(user_query: str) -> str:
    chunks = retrieve_chunks(user_query)
    return generate_answer(user_query, chunks)

@observe()  # child span: retrieval
def retrieve_chunks(query: str) -> list[str]:
    # your vector DB call here
    results = ["chunk A", "chunk B"]  # placeholder
    langfuse_context.update_current_observation(metadata={"num_chunks": len(results)})
    return results

@observe(as_type="generation")  # child span: LLM call, tracked as a generation
def generate_answer(query: str, chunks: list[str]) -> str:
    context = "\n".join(chunks)
    response = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[
            {"role": "system", "content": "Answer using the context below.\n" + context},
            {"role": "user", "content": query},
        ],
    )
    return response.choices[0].message.content

result = answer_question("What is the refund policy?")
print(result)
